	if len(input) == 0 {
		return &gqlmodel.DispatchBulkAssignResult{
			Results: []*gqlmodel.DispatchAssignResult{},
		}, nil
	}
	if len(input) > maxBulkAssignBatch {
		return nil, errortypes.NewBusinessError(
			"Too many moves in a single assignment request",
		).WithParam("limit", strconv.Itoa(maxBulkAssignBatch))
	}

	tenant := tenantInfo(authCtx)
	results := make([]*gqlmodel.DispatchAssignResult, 0, len(input))

	// Each move is applied independently: one bad pairing must not cost a dispatcher the
	// other nine assignments in the batch.
	for _, item := range input {
		results = append(results, r.assignOneMove(ctx, tenant, item))
	}

	return summarizeBulkResults(results), nil
