// DispatchUnassignMoves is the resolver for the dispatchUnassignMoves field.
func (r *mutationResolver) DispatchUnassignMoves(
	ctx context.Context,
	moveIds []string,
) (*gqlmodel.DispatchBulkAssignResult, error) {
	authCtx, err := r.requirePermission(
		ctx,
		permission.ResourceShipmentMove,
		permission.OpUnassign,
	)
	if err != nil {
		return nil, err
	}

	if len(moveIds) > maxBulkAssignBatch {
		return nil, errortypes.NewBusinessError(
			"Too many moves in a single unassignment request",
		).WithParam("limit", strconv.Itoa(maxBulkAssignBatch))
	}

	tenant := tenantInfo(authCtx)
	results := make([]*gqlmodel.DispatchAssignResult, 0, len(moveIds))

	for _, rawID := range moveIds {
		result := &gqlmodel.DispatchAssignResult{
			MoveID:   rawID,
			Findings: []*gqlmodel.DispatchFinding{},
		}

		moveID, parseErr := pulid.Parse(rawID)
		if parseErr != nil {
			result.Error = errorMessage(parseErr)
			results = append(results, result)
			continue
		}

		unassignErr := r.assignmentService.Unassign(
			ctx,
			&repositories.UnassignShipmentMoveRequest{
				TenantInfo:     tenant,
				ShipmentMoveID: moveID,
			},
		)
		if unassignErr != nil {
			result.Error = errorMessage(unassignErr)
			result.Findings = findingsFromError(unassignErr)
			results = append(results, result)
			continue
		}

		result.Success = true
		results = append(results, result)
	}

	return summarizeBulkResults(results), nil
}

